args.sql:
CREATE OR REPLACE FUNCTION calc_effective_leverage(
    position_leverage TEXT, 
    position_value NUMERIC, 
    balance NUMERIC
) RETURNS NUMERIC AS $$
BEGIN
    RETURN (position_leverage::NUMERIC * (position_value / balance));
END;
$$ LANGUAGE plpgsql;

